broken:
fn main() {
    let mut expenses = Vec::new();
    let first = &mut expenses;
    let second = &mut expenses;
    first.push(1);
    second.push(2);
}

rustc:
error[E0499]: cannot borrow `expenses` as mutable more than once at a time
 --> example.rs:4:18
  |
3 |     let first = &mut expenses;
  |                 ------------- first mutable borrow occurs here
4 |     let second = &mut expenses;
  |                  ^^^^^^^^^^^^^ second mutable borrow occurs here
5 |     first.push(1);
  |     ----- first borrow later used here

fix:
fn main() {
    let mut expenses = Vec::new();
    {
        let first = &mut expenses;
        first.push(1);
    }
    let second = &mut expenses;
    second.push(2);
    println!("{expenses:?}");
}

broken:
