    let view = &expenses;
    expenses.push(1);
    println!("{view:?}");
}

rustc:
error[E0502]: cannot borrow `expenses` as mutable because it is also borrowed as immutable
 --> example.rs:4:5
  |
3 |     let view = &expenses;
  |                --------- immutable borrow occurs here
4 |     expenses.push(1);
  |     ^^^^^^^^^^^^^^^^ mutable borrow occurs here
5 |     println!("{view:?}");
  |               -------- immutable borrow later used here

fix:
fn main() {
    let mut expenses = Vec::new();
    {
        let view = &expenses;
        println!("{view:?}");
    }
    expenses.push(1);
}

